mapper.select:
SELECT * FROM (

 WHERE H.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND H.EMP_OFFICE = '15119'

   AND (H.EMPID LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%'
        OR CONVERTTOUNSIGN(UPPER(H.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%')


   AND H.DEPTNO IN (SELECT D.DEPTNO
                      FROM HR_DEPARTMENT D
                     START WITH D.DEPTNO IN

            #{deptNo, jdbcType=VARCHAR}

                   CONNECT BY PRIOR D.DEPTNO = D.PARENT_DEPT_NO)

 ORDER BY H.EMPID
) WHERE ROWNUM <= #{maxRows, jdbcType=NUMERIC}


WHERE H.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND H.EMPID = #{empId, jdbcType=VARCHAR}
  AND ROWNUM = 1
